def template(encoded):
    return json.loads(zlib.decompress(base64.b85decode(encoded)).decode())

def synthetic_reports():
    reports = []
    for position, (mode, index, _, _) in enumerate(RUNS):
        report = copy.deepcopy(template(COM02_TEMPLATE if mode == "com-02" else COM04_TEMPLATE))
        nonce = hashlib.sha256(f"synthetic-{position}".encode()).hexdigest()
        report["prep_source_inventory"]["fresh_run_index"] = index
        report["prep_source_inventory"]["nonce"] = nonce
        report["run_id"] = report["prep_source_inventory"]["run_id"] = f"{mode}-v2-fresh-{index}-{nonce}"
        reports.append(report)
    return reports

def write_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8", newline="\n")

class GateTests(unittest.TestCase):
    def test_fixed_gate(self): self.assertEqual(verify_coordination()["status"], "ready_for_record_replay")
    def reject(self, mutate):
        runs = [list(item) for item in RUNS]; mutate(runs)
        with self.assertRaises(VerificationError): verify_coordination(tuple(tuple(item) for item in runs))
    def test_run_id_mutation(self): self.reject(lambda runs: runs[1].__setitem__(2, runs[0][2]))
    def test_challenge_mutation(self): self.reject(lambda runs: runs[2].__setitem__(3, runs[0][3]))
    def test_mode_order_mutation(self): self.reject(lambda runs: runs[0].__setitem__(0, "com-04"))
    def test_index_mutation(self): self.reject(lambda runs: runs[3].__setitem__(1, 1))
    def test_challenge_length_mutation(self): self.reject(lambda runs: runs[0].__setitem__(3, "0" * 63))
    def test_real_git_exact_three_gate_custody(self):
        with tempfile.TemporaryDirectory() as directory:
            repo = Path(directory)
            def git(*args):
                result = subprocess.run(["git", "-C", str(repo), *args], capture_output=True, text=True, check=True)
                return result.stdout.strip()
            git("init", "-q"); git("config", "user.email", "gate@example.invalid"); git("config", "user.name", "gate")
            (repo / "seed").write_text("prep", encoding="utf-8"); git("add", "seed"); git("commit", "-qm", "prep"); parent = git("rev-parse", "HEAD")
            for path in GATE_FILES:
                target = repo / path; target.parent.mkdir(parents=True, exist_ok=True); target.write_text(path, encoding="utf-8")
            git("add", *sorted(GATE_FILES)); git("commit", "-qm", "gate"); gate = git("rev-parse", "HEAD")
            self.assertTrue(verify_gate_commit(repo, gate, parent))
            (repo / "extra").write_text("x", encoding="utf-8"); git("add", "extra"); git("commit", "-qm", "not exact")
            with self.assertRaises(VerificationError): verify_gate_commit(repo, git("rev-parse", "HEAD"), gate)
    def test_nonfinite_json_token_is_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "report.json"; path.write_text('{"value":NaN}', encoding="utf-8")
            with self.assertRaises(ValueError): load_report(path)
    def test_duplicate_yaml_key_is_rejected(self):
        with self.assertRaises(VerificationError): yaml.load("a: 1\na: 2\n", Loader=StrictLoader)
    def test_nested_shape_distinguishes_bool_int_float_and_extra(self):
        baseline = {"flag": True, "count": 1, "value": 1.0, "nested": {"x": []}}
        for mutation in (
            {**baseline, "flag": 1}, {**baseline, "count": True},
            {**baseline, "value": 1}, {**baseline, "extra": None},
        ):
            self.assertNotEqual(shape_sha(baseline), shape_sha(mutation))
    def test_exact_audit_is_derived_from_gate_reports_and_aggregate(self):
        manifest = {"gate": {"commit": "a" * 40}, "reports": [{"path": "r", "sha256": "b" * 64}], "aggregate": {"path": "a", "sha256": "c" * 64}}
        audit = expected_audit(manifest)
        self.assertIn("GATE_COMMIT: " + "a" * 40, audit)
        self.assertIn("REPORT: r " + "b" * 64, audit)
        self.assertIn("AGGREGATE: a " + "c" * 64, audit)

    def test_complete_future_bundle_and_coordinated_mutations(self):
        source = Path(__file__).resolve().parents[1]
        upstream = Path(os.environ.get("SIPI_COM_UPSTREAM", r"C:\Users\z3312\code\COM"))
        self.assertTrue(upstream.is_dir(), "pinned Agent-COM repository is required")
        with tempfile.TemporaryDirectory() as directory:
            repo = Path(directory)
            def git(*args):
                return subprocess.run(["git", "-C", str(repo), *args], capture_output=True, text=True, check=True).stdout.strip()
            git("init", "-q"); git("config", "user.email", "gate@example.invalid"); git("config", "user.name", "gate"); git("config", "core.autocrlf", "false")
            (repo / "seed").write_text("interposed", encoding="utf-8", newline="\n"); git("add", "seed"); git("commit", "-qm", "interposed"); parent = git("rev-parse", "HEAD")
            for path in GATE_FILES:
                target = repo / path; target.parent.mkdir(parents=True, exist_ok=True); target.write_bytes((source / path).read_bytes())
            git("add", *sorted(GATE_FILES)); git("commit", "-qm", "gate"); gate = git("rev-parse", "HEAD")
            self.assertTrue(verify_gate_commit(repo, gate, parent))
            paths = [
                "docs/baselines/com-02-result-surface-formal-run1.v1.json", "docs/baselines/com-02-result-surface-formal-run2.v1.json",
                "docs/baselines/com-04-result-surface-formal-run1.v1.json", "docs/baselines/com-04-result-surface-formal-run2.v1.json",
            ]
            reports = synthetic_reports()
            for path, report in zip(paths, reports): write_json(repo / path, report)
            aggregate_path = repo / "docs/baselines/com-02-04-result-surface-formal-aggregate.v1.json"
            command = ["python", str(repo / "tools/aggregate_com_02_04_result_surface.py"), "--repo", str(source), "--upstream-repo", str(upstream)]
            for path in paths: command.extend(["--report", str(repo / path)])
            command.extend(["--output", str(aggregate_path)])
            subprocess.run(command, check=True, capture_output=True, timeout=60)
            sha = lambda path: hashlib.sha256(path.read_bytes()).hexdigest()
            tools = []
            for path in sorted(GATE_FILES):
                entry = git("ls-tree", gate, "--", path).split(); raw = subprocess.check_output(["git", "-C", str(repo), "cat-file", "blob", entry[2]])
                tools.append({"path": path, "blob": entry[2], "bytes": len(raw), "sha256": hashlib.sha256(raw).hexdigest()})
            claims = {"prep_source_inventory": True, "fresh_nonce": True, "coordination_labels_are_not_execution_identity": True, "full_report_hashes": True, "upstream_numeric_parity": False, "port_order_result_wire": False}
            manifest = {"schema": "sipi.com-02-04.result-surface-formal.v1", "status": "passed_scoped", "gate": {"commit": gate, "tree": git("show", "-s", "--format=%T", gate), "tools": tools}, "reports": [{"path": path, "sha256": sha(repo / path), "record_label": run[2], "coordination_label_sha256": run[3]} for path, run in zip(paths, RUNS)], "aggregate": {"path": "docs/baselines/com-02-04-result-surface-formal-aggregate.v1.json", "sha256": sha(aggregate_path)}, "audit": {"path": "docs/baselines/audits/2026-08-29-com-02-04-result-surface-formal.md", "sha256": ""}, "semantic_anchors": SEMANTIC_ANCHORS, "claims": claims}
            audit_path = repo / manifest["audit"]["path"]; audit_path.parent.mkdir(parents=True, exist_ok=True); audit_path.write_text(expected_audit(manifest), encoding="utf-8", newline="\n"); manifest["audit"]["sha256"] = sha(audit_path)
            write_json(repo / "docs/baselines/com-02-04-result-surface-formal.v1.yaml", manifest)
            git("add", *sorted(FORMAL_FILES)); git("commit", "-qm", "record"); record = git("rev-parse", "HEAD")
            self.assertTrue(verify_record_commit(repo, record, gate))
            self.assertTrue(verify_record_documents(repo, gate, upstream, source))

            def rejected(mutate):
                mutated = copy.deepcopy(synthetic_reports()); mutate(mutated)
                with tempfile.TemporaryDirectory() as output_dir:
                    report_paths = []
                    for index, value in enumerate(mutated):
                        path = Path(output_dir) / f"r{index}.json"; write_json(path, value); report_paths.append(path)
                    output = Path(output_dir) / "aggregate.json"
                    args = ["python", str(source / "tools/aggregate_com_02_04_result_surface.py"), "--repo", str(source), "--upstream-repo", str(upstream)]
                    for path in report_paths: args.extend(["--report", str(path)])
                    args.extend(["--output", str(output)])
                    self.assertNotEqual(subprocess.run(args, capture_output=True, timeout=60).returncode, 0)
            rejected(lambda r: r[0]["candidate"].__setitem__("binary_sha256", "0" * 64))
            rejected(lambda r: r[0]["prep_source_inventory"]["toolchain"]["cargo"].__setitem__("role", "rustc"))
            rejected(lambda r: r[0]["prep_source_inventory"]["build"].__setitem__("returncode", 1))
